begin;
update public.questions set question_text = $q$If there are no traffic signals, you should yield to pedestrians at what location?$q$, answers = $q${"A": "Only a marked crosswalk", "B": "A marked or unmarked crosswalk", "C": "Any sidewalk driveway", "D": "Only an intersection"}$q$::jsonb, correct_answer = $q$B$q$, explanation = $q$When there are no traffic signals, drivers must slow down or stop to yield to pedestrians in crosswalks, whether marked or unmarked.$q$, question_text_es = $q$Si no hay semáforos, ¿en qué lugar debe ceder el paso a los peatones?$q$, answers_es = $q${"A": "Solo en un cruce marcado", "B": "En un cruce marcado o no marcado", "C": "En cualquier entrada de acera", "D": "Solo en una intersección"}$q$::jsonb, explanation_es = $q$Cuando no hay semáforos, los conductores deben reducir la velocidad o detenerse para ceder el paso a los peatones en los cruces peatonales, estén marcados o no.$q$ where id = $q$4fcff093-1c73-4529-8743-c405e67b9605$q$::uuid;
update public.questions set question_text = $q$Where should you always look both ways before proceeding?$q$, answers = $q${"A": "At intersections", "B": "Only at green lights", "C": "Only on highways", "D": "Only in parking lots"}$q$::jsonb, correct_answer = $q$A$q$, explanation = $q$Always look both ways before proceeding through an intersection. This helps you spot traffic, pedestrians, or hazards even when you have the right-of-way.$q$, question_text_es = $q$¿Dónde siempre debe mirar a ambos lados antes de seguir?$q$, answers_es = $q${"A": "En las intersecciones", "B": "Solo con luz verde", "C": "Solo en las autopistas", "D": "Solo en los estacionamientos"}$q$::jsonb, explanation_es = $q$Siempre debe mirar a ambos lados antes de avanzar por una intersección. Esto le ayuda a ver tráfico, peatones o peligros, incluso cuando tiene el derecho de paso.$q$ where id = $q$c917f1ad-e742-4a8d-bcb5-1f4a959aaf50$q$::uuid;
update public.questions set question_text = $q$You approach a STOP sign with a stop line. Where must you stop?$q$, answers = $q${"A": "Inside the intersection", "B": "In the crosswalk", "C": "Past the stop line", "D": "At the stop line"}$q$::jsonb, correct_answer = $q$D$q$, explanation = $q$When there is a stop line, stop at the line. If there is no line, stop before the crosswalk; if there is neither, stop before entering the intersection.$q$, question_text_es = $q$Se acerca a una señal de ALTO con línea de alto. ¿Dónde debe detenerse?$q$, answers_es = $q${"A": "Dentro de la intersección", "B": "Sobre el cruce peatonal", "C": "Después de la línea", "D": "En la línea de alto"}$q$::jsonb, explanation_es = $q$Si hay línea de alto, deténgase en la línea. Si no la hay, deténgase antes del cruce peatonal; si no hay ninguno, antes de entrar a la intersección.$q$ where id = $q$f2f11c2a-5099-44a2-9fd9-11fb88cc2895$q$::uuid;
update public.questions set question_text = $q$At a railroad crossing with only a stop sign, when may you proceed?$q$, answers = $q${"A": "After one full minute.", "B": "When no children are present.", "C": "When no pedestrians are nearby.", "D": "After stopping, when no train is approaching."}$q$::jsonb, correct_answer = $q$D$q$, explanation = $q$At a railroad crossing with a stop sign, you must stop and proceed only when no train is approaching and it is safe to cross. Answer A matches that rule.$q$, question_text_es = $q$En un cruce de ferrocarril con solo una señal de alto, ¿cuándo puede continuar?$q$, answers_es = $q${"A": "Después de un minuto completo.", "B": "Cuando no haya niños presentes.", "C": "Cuando no haya peatones cerca.", "D": "Después de parar, cuando no se acerque un tren."}$q$::jsonb, explanation_es = $q$En un cruce de ferrocarril con una señal de alto, debe detenerse y continuar solo cuando no se acerque ningún tren y sea seguro cruzar. La respuesta A coincide con esa regla.$q$ where id = $q$9aff4da1-492e-4b79-9b68-0ef0e718253d$q$::uuid;
update public.questions set question_text = $q$When are roads usually most slippery during rain?$q$, answers = $q${"A": "Right after rain begins", "B": "After hours of rain", "C": "Only at night", "D": "Only in heavy storms"}$q$::jsonb, correct_answer = $q$A$q$, explanation = $q$Roads are most slippery just after rain begins, when water mixes with oil and dirt on the surface. Slow down and leave extra space.$q$, question_text_es = $q$¿Cuándo suelen estar las carreteras más resbaladizas durante la lluvia?$q$, answers_es = $q${"A": "Justo al empezar a llover", "B": "Tras horas de lluvia", "C": "Solo de noche", "D": "Solo en tormentas fuertes"}$q$::jsonb, explanation_es = $q$El camino está más resbaloso justo cuando empieza a llover, porque el agua se mezcla con aceite y polvo. Reduzca la velocidad y deje más espacio.$q$ where id = $q$0f8878d5-a802-4c05-8782-9f427e78cabc$q$::uuid;
update public.questions set question_text = $q$When approaching a railroad crossing, what should you do?$q$, answers = $q${"A": "Speed up to cross quickly", "B": "Stop on the tracks", "C": "Ignore warning signs", "D": "Slow down and prepare to stop"}$q$::jsonb, correct_answer = $q$D$q$, explanation = $q$As you approach a railroad crossing, you should slow down and be ready to stop. This gives you time to look for a train and react safely if one is coming.$q$, question_text_es = $q$Al acercarse a un cruce de ferrocarril, ¿qué debe hacer?$q$, answers_es = $q${"A": "Acelerar para cruzar rápido", "B": "Detenerse sobre las vías", "C": "Ignorar las señales de advertencia", "D": "Reducir la velocidad y prepararse para detenerse"}$q$::jsonb, explanation_es = $q$Al acercarse a un cruce de ferrocarril, debe reducir la velocidad y estar listo para detenerse. Esto le da tiempo para buscar un tren y reaccionar con seguridad si uno se acerca.$q$ where id = $q$b3e8147a-f8ac-43a7-b2eb-34fed8308f3b$q$::uuid;
update public.questions set question_text = $q$Where should an infant or small child ride in a vehicle with airbags?$q$, answers = $q${"A": "In the cargo area", "B": "On an adult's lap", "C": "In the front seat", "D": "In the back seat"}$q$::jsonb, correct_answer = $q$D$q$, explanation = $q$Infants and small children should ride in the back seat, properly restrained. A front seat with an active airbag can seriously injure a child, even in a low-speed crash.$q$, question_text_es = $q$¿Dónde debe viajar un bebé o niño pequeño en un vehículo con bolsas de aire?$q$, answers_es = $q${"A": "En el área de carga", "B": "En el regazo de un adulto", "C": "En el asiento delantero", "D": "En el asiento trasero"}$q$::jsonb, explanation_es = $q$Los bebés y niños pequeños deben viajar en el asiento trasero, correctamente sujetos. Un asiento delantero con una bolsa de aire activa puede lesionar gravemente a un niño, incluso en un choque a baja velocidad.$q$ where id = $q$f87dc356-9a12-400b-88c0-9676d1b2c5f2$q$::uuid;
update public.questions set question_text = $q$If a driver is tailgating you, what should you do if a right lane is open?$q$, answers = $q${"A": "Speed up to get away", "B": "Brake suddenly to warn them", "C": "Move over to the right", "D": "Stop in your lane"}$q$::jsonb, correct_answer = $q$C$q$, explanation = $q$When another driver is tailgating you, move to the right if a lane is open. This lets the tailgater pass and helps avoid conflict or a rear-end crash.$q$, question_text_es = $q$Si un conductor lo sigue muy de cerca, ¿qué debe hacer si hay un carril derecho abierto?$q$, answers_es = $q${"A": "Acelere para alejarse", "B": "Frene de repente para avisarle", "C": "Cámbiese al carril derecho", "D": "Deténgase en su carril"}$q$::jsonb, explanation_es = $q$Cuando otro conductor lo sigue muy de cerca, cámbiese a la derecha si hay un carril abierto. Esto permite que pase y ayuda a evitar un conflicto o un choque por detrás.$q$ where id = $q$091a7453-fb38-466b-a39c-b187578423f7$q$::uuid;
update public.questions set question_text = $q$When must you obey a traffic officer's order to stop?$q$, answers = $q${"A": "Only at a red light", "B": "Only in a school zone", "C": "Only at a stop sign", "D": "Whenever an officer directs you"}$q$::jsonb, correct_answer = $q$D$q$, explanation = $q$You must stop whenever a traffic officer directs you to stop. An officer's directions override signs and signals.$q$, question_text_es = $q$¿Cuándo debe obedecer la orden de un agente de tránsito de detenerse?$q$, answers_es = $q${"A": "Solo en una luz roja", "B": "Solo en una zona escolar", "C": "Solo en una señal de alto", "D": "Siempre que un agente se lo indique"}$q$::jsonb, explanation_es = $q$Debe detenerse siempre que un agente de tránsito le indique que se detenga. Las instrucciones del agente tienen prioridad sobre las señales y los semáforos.$q$ where id = $q$39cce534-caa2-4877-acc3-0578cacb32e6$q$::uuid;
update public.questions set question_text = $q$When should you slow down on a wet or slippery road?$q$, answers = $q${"A": "Whenever traction is reduced", "B": "Only when turning left", "C": "Only near stop signs", "D": "Only if other cars splash water"}$q$::jsonb, correct_answer = $q$A$q$, explanation = $q$Slow down whenever the road is wet or slippery because reduced traction increases crash risk. Lower speed gives you more time to react and helps maintain control.$q$, question_text_es = $q$¿Cuándo debe reducir la velocidad en una carretera mojada o resbaladiza?$q$, answers_es = $q${"A": "Siempre que la tracción sea menor", "B": "Solo al girar a la izquierda", "C": "Solo cerca de señales de alto", "D": "Solo si otros autos salpican agua"}$q$::jsonb, explanation_es = $q$Reduzca la velocidad siempre que la carretera esté mojada o resbaladiza porque la menor tracción aumenta el riesgo de choque. Una velocidad más baja le da más tiempo para reaccionar y ayuda a mantener el control.$q$ where id = $q$845118a7-2422-417b-94ba-408620dc78cd$q$::uuid;
update public.questions set question_text = $q$If a collision is unavoidable, what should you try to hit?$q$, answers = $q${"A": "An oncoming moving vehicle", "B": "A rigid concrete barrier", "C": "Something that will give way", "D": "The center of a parked truck"}$q$::jsonb, correct_answer = $q$C$q$, explanation = $q$If a collision is unavoidable, try to hit something that will give way rather than something rigid. This can reduce the force of impact and lessen injuries.$q$, question_text_es = $q$Si una colisión es inevitable, ¿qué debería tratar de golpear?$q$, answers_es = $q${"A": "Un vehículo que viene de frente", "B": "Una barrera rígida de concreto", "C": "Algo que ceda al impacto", "D": "El centro de un camión estacionado"}$q$::jsonb, explanation_es = $q$Si una colisión es inevitable, trate de golpear algo que ceda al impacto en lugar de algo rígido. Esto puede reducir la fuerza del impacto y disminuir las lesiones.$q$ where id = $q$15ea1a56-8d53-4437-9090-2fca4d7eece8$q$::uuid;
update public.questions set question_text = $q$If your windshield wipers fail in rain or snow, what should you do first?$q$, answers = $q${"A": "Speed up to clear water", "B": "Pull off the road safely", "C": "Keep driving slowly", "D": "Open a window for visibility"}$q$::jsonb, correct_answer = $q$B$q$, explanation = $q$If your wipers fail during rain or snow, reduced visibility makes continuing dangerous. Slow down and pull off the road safely until you can restore visibility.$q$, question_text_es = $q$Si los limpiaparabrisas fallan con lluvia o nieve, ¿qué debe hacer primero?$q$, answers_es = $q${"A": "Acelerar para quitar el agua", "B": "Orillarse de manera segura", "C": "Seguir manejando despacio", "D": "Abrir una ventana para ver"}$q$::jsonb, explanation_es = $q$Si los limpiaparabrisas fallan durante lluvia o nieve, la visibilidad reducida hace peligroso continuar. Disminuya la velocidad y oríllese de manera segura hasta que pueda recuperar la visibilidad.$q$ where id = $q$ae87c154-eb18-42b1-bbe5-f425f4816685$q$::uuid;
commit;
