insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Both cars arrive at this four-way stop at the same time. Which car goes first?$q$, $q${"A": "Car A", "B": "Car B", "C": "Both at once", "D": "The faster car"}$q$::jsonb, $q$A$q$, $q$When two cars reach a four-way stop at the same time, the driver on the left yields to the driver on the right. Car A is on Car B's right, so Car A goes first.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-fourway-right-0.png$q$, $q$Ambos autos llegan a este alto de cuatro vías al mismo tiempo. ¿Qué auto pasa primero?$q$, $q${"A": "El auto A", "B": "El auto B", "C": "Ambos a la vez", "D": "El más rápido"}$q$::jsonb, $q$Cuando dos autos llegan a un alto de cuatro vías al mismo tiempo, el conductor de la izquierda cede el paso al de la derecha. El auto A está a la derecha del auto B, así que el auto A pasa primero.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Both cars arrive at this four-way stop at the same time. Which car goes first?$q$, $q${"A": "The faster car", "B": "Car A", "C": "Both at once", "D": "Car B"}$q$::jsonb, $q$D$q$, $q$When two cars reach a four-way stop at the same time, the driver on the left yields to the driver on the right. Car B is on Car A's right, so Car B goes first.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-fourway-right-90s.png$q$, $q$Ambos autos llegan a este alto de cuatro vías al mismo tiempo. ¿Qué auto pasa primero?$q$, $q${"A": "El más rápido", "B": "El auto A", "C": "Ambos a la vez", "D": "El auto B"}$q$::jsonb, $q$Cuando dos autos llegan a un alto de cuatro vías al mismo tiempo, el conductor de la izquierda cede el paso al de la derecha. El auto B está a la derecha del auto A, así que el auto B pasa primero.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Both cars arrive at this four-way stop at the same time. Which car goes first?$q$, $q${"A": "The faster car", "B": "Both at once", "C": "Car B", "D": "Car A"}$q$::jsonb, $q$D$q$, $q$When two cars reach a four-way stop at the same time, the driver on the left yields to the driver on the right. Car A is on Car B's right, so Car A goes first.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-fourway-right-270.png$q$, $q$Ambos autos llegan a este alto de cuatro vías al mismo tiempo. ¿Qué auto pasa primero?$q$, $q${"A": "El más rápido", "B": "Ambos a la vez", "C": "El auto B", "D": "El auto A"}$q$::jsonb, $q$Cuando dos autos llegan a un alto de cuatro vías al mismo tiempo, el conductor de la izquierda cede el paso al de la derecha. El auto A está a la derecha del auto B, así que el auto A pasa primero.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$There are no signs or signals at this intersection, and both cars arrive at the same time. Which car must yield?$q$, $q${"A": "The faster car", "B": "Neither car", "C": "Car B", "D": "Car A"}$q$::jsonb, $q$C$q$, $q$At an intersection without signs or signals, yield to the vehicle on your right when you arrive at the same time. Car A is on Car B's right, so Car B yields.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-uncontrolled-right-0.png$q$, $q$No hay señales ni semáforos en esta intersección y ambos autos llegan al mismo tiempo. ¿Qué auto debe ceder el paso?$q$, $q${"A": "El más rápido", "B": "Ninguno", "C": "El auto B", "D": "El auto A"}$q$::jsonb, $q$En una intersección sin señales ni semáforos, cede el paso al vehículo de tu derecha si llegan al mismo tiempo. El auto A está a la derecha del auto B, así que el auto B cede el paso.$q$);
