insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Both cars stop at this four-way stop at the same time. Car A is going straight and Car B is turning left. Which car goes first?$q$, $q${"A": "Both at once", "B": "Car B", "C": "Car A", "D": "The closer car"}$q$::jsonb, $q$C$q$, $q$When two drivers facing each other arrive together, the driver turning left yields to the driver going straight. Car A goes first.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-fourway-left-vs-straight-0.png$q$, $q$Ambos autos se detienen en este alto de cuatro vías al mismo tiempo. El auto A sigue derecho y el auto B gira a la izquierda. ¿Qué auto pasa primero?$q$, $q${"A": "Ambos a la vez", "B": "El auto B", "C": "El auto A", "D": "El más cercano"}$q$::jsonb, $q$Cuando dos conductores de frente llegan juntos, el que gira a la izquierda cede el paso al que sigue derecho. El auto A pasa primero.$q$);
