insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Both cars have a green light. Car B wants to turn left and Car A is going straight. Who has the right-of-way?$q$, $q${"A": "Car B", "B": "Car A", "C": "First to enter", "D": "Neither car"}$q$::jsonb, $q$B$q$, $q$On a green light without a green arrow, a driver turning left must yield to oncoming traffic going straight. Car A has the right-of-way.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-green-left-turn-0.png$q$, $q$Ambos autos tienen luz verde. El auto B quiere girar a la izquierda y el auto A sigue derecho. ¿Quién tiene el derecho de paso?$q$, $q${"A": "El auto B", "B": "El auto A", "C": "El primero en entrar", "D": "Ninguno"}$q$::jsonb, $q$Con luz verde sin flecha verde, quien gira a la izquierda debe ceder el paso al tráfico de frente que sigue derecho. El auto A tiene el derecho de paso.$q$);
