insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car B is entering the roundabout and Car A is already in it. Who has the right-of-way?$q$, $q${"A": "Car A", "B": "Neither car", "C": "The faster car", "D": "Car B"}$q$::jsonb, $q$A$q$, $q$Drivers entering a roundabout must yield to traffic already circulating. Car A is already in the roundabout.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-roundabout-entry-270.png$q$, $q$El auto B está entrando a la glorieta y el auto A ya está dentro. ¿Quién tiene el derecho de paso?$q$, $q${"A": "El auto A", "B": "Ninguno", "C": "El más rápido", "D": "El auto B"}$q$::jsonb, $q$Quien entra a una glorieta debe ceder el paso al tráfico que ya circula en ella. El auto A ya está dentro.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car A is turning right on a green light while a person is crossing the street. Who goes first?$q$, $q${"A": "Neither, both wait", "B": "Car A", "C": "The pedestrian", "D": "First to move"}$q$::jsonb, $q$C$q$, $q$A green light does not give you the right-of-way over people in the crosswalk. When turning, yield to pedestrians crossing the street you are turning into.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-pedestrian-right-turn-0.png$q$, $q$El auto A gira a la derecha con luz verde mientras una persona cruza la calle. ¿Quién pasa primero?$q$, $q${"A": "Ninguno, ambos esperan", "B": "El auto A", "C": "El peatón", "D": "El primero en avanzar"}$q$::jsonb, $q$La luz verde no te da el derecho de paso sobre las personas en el cruce peatonal. Al girar, cede el paso a los peatones que cruzan la calle hacia la que giras.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car B is turning right on a green light while a person is crossing the street. Who goes first?$q$, $q${"A": "The pedestrian", "B": "First to move", "C": "Neither, both wait", "D": "Car B"}$q$::jsonb, $q$A$q$, $q$A green light does not give you the right-of-way over people in the crosswalk. When turning, yield to pedestrians crossing the street you are turning into.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-pedestrian-right-turn-90s.png$q$, $q$El auto B gira a la derecha con luz verde mientras una persona cruza la calle. ¿Quién pasa primero?$q$, $q${"A": "El peatón", "B": "El primero en avanzar", "C": "Ninguno, ambos esperan", "D": "El auto B"}$q$::jsonb, $q$La luz verde no te da el derecho de paso sobre las personas en el cruce peatonal. Al girar, cede el paso a los peatones que cruzan la calle hacia la que giras.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car A is turning right on a green light while a person is crossing the street. Who goes first?$q$, $q${"A": "Neither, both wait", "B": "Car A", "C": "The pedestrian", "D": "First to move"}$q$::jsonb, $q$C$q$, $q$A green light does not give you the right-of-way over people in the crosswalk. When turning, yield to pedestrians crossing the street you are turning into.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-pedestrian-right-turn-270.png$q$, $q$El auto A gira a la derecha con luz verde mientras una persona cruza la calle. ¿Quién pasa primero?$q$, $q${"A": "Ninguno, ambos esperan", "B": "El auto A", "C": "El peatón", "D": "El primero en avanzar"}$q$::jsonb, $q$La luz verde no te da el derecho de paso sobre las personas en el cruce peatonal. Al girar, cede el paso a los peatones que cruzan la calle hacia la que giras.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$An ambulance with its lights and siren on is coming up behind Car A. What should Car A do?$q$, $q${"A": "Speed up", "B": "Pull over and stop", "C": "Use the other lane", "D": "Stop in its lane"}$q$::jsonb, $q$B$q$, $q$When an emergency vehicle approaches with lights and siren, pull over to the right edge of the road, stop, and stay there until it has passed.$q$, $q$Sharing the Road$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-emergency-vehicle-0.png$q$, $q$Una ambulancia con luces y sirena encendidas se acerca por detrás del auto A. ¿Qué debe hacer el auto A?$q$, $q${"A": "Acelerar", "B": "Orillarse y detenerse", "C": "Pasar al otro carril", "D": "Frenar en su carril"}$q$::jsonb, $q$Cuando se acerca un vehículo de emergencia con luces y sirena, oríllate al lado derecho del camino, detente y espera a que pase.$q$);
