insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$The school bus has stopped with red lights flashing and its stop arm out on this two-lane road. Which cars must stop?$q$, $q${"A": "Only Car A", "B": "Both cars", "C": "Neither car", "D": "Only Car B"}$q$::jsonb, $q$B$q$, $q$On a two-lane road, traffic in both directions must stop for a school bus with flashing red lights and an extended stop arm, and stay stopped until the lights turn off.$q$, $q$Sharing the Road$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-school-bus-two-lane-0.png$q$, $q$El autobús escolar se detuvo con luces rojas intermitentes y el brazo de alto extendido en este camino de dos carriles. ¿Qué autos deben detenerse?$q$, $q${"A": "Solo el auto A", "B": "Ambos autos", "C": "Ninguno", "D": "Solo el auto B"}$q$::jsonb, $q$En un camino de dos carriles, el tráfico en ambas direcciones debe detenerse ante un autobús escolar con luces rojas intermitentes y el brazo de alto extendido, hasta que las luces se apaguen.$q$);
