insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car B is on the on-ramp and Car A is in the right lane of the highway. Who must yield?$q$, $q${"A": "Neither car", "B": "The slower car", "C": "Car A", "D": "Car B"}$q$::jsonb, $q$D$q$, $q$Drivers entering a highway must yield to traffic already on it and adjust speed to merge into a safe gap. Car B yields.$q$, $q$Lane Usage & Highway Driving$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-highway-merge-0.png$q$, $q$El auto B está en la rampa de entrada y el auto A va en el carril derecho de la autopista. ¿Quién debe ceder el paso?$q$, $q${"A": "Ninguno", "B": "El más lento", "C": "El auto A", "D": "El auto B"}$q$::jsonb, $q$Quien entra a una autopista debe ceder el paso al tráfico que ya circula y ajustar su velocidad para incorporarse en un espacio seguro. El auto B cede el paso.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car A is on the on-ramp and Car B is in the right lane of the highway. Who must yield?$q$, $q${"A": "The slower car", "B": "Neither car", "C": "Car A", "D": "Car B"}$q$::jsonb, $q$C$q$, $q$Drivers entering a highway must yield to traffic already on it and adjust speed to merge into a safe gap. Car A yields.$q$, $q$Lane Usage & Highway Driving$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-highway-merge-90s.png$q$, $q$El auto A está en la rampa de entrada y el auto B va en el carril derecho de la autopista. ¿Quién debe ceder el paso?$q$, $q${"A": "El más lento", "B": "Ninguno", "C": "El auto A", "D": "El auto B"}$q$::jsonb, $q$Quien entra a una autopista debe ceder el paso al tráfico que ya circula y ajustar su velocidad para incorporarse en un espacio seguro. El auto A cede el paso.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car B is on the on-ramp and Car A is in the right lane of the highway. Who must yield?$q$, $q${"A": "Neither car", "B": "Car B", "C": "Car A", "D": "The slower car"}$q$::jsonb, $q$B$q$, $q$Drivers entering a highway must yield to traffic already on it and adjust speed to merge into a safe gap. Car B yields.$q$, $q$Lane Usage & Highway Driving$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-highway-merge-270.png$q$, $q$El auto B está en la rampa de entrada y el auto A va en el carril derecho de la autopista. ¿Quién debe ceder el paso?$q$, $q${"A": "Ninguno", "B": "El auto B", "C": "El auto A", "D": "El más lento"}$q$::jsonb, $q$Quien entra a una autopista debe ceder el paso al tráfico que ya circula y ajustar su velocidad para incorporarse en un espacio seguro. El auto B cede el paso.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car B has a red light and wants to turn right. Car A has a green light. What must Car B do?$q$, $q${"A": "Turn first", "B": "Flash lights and go", "C": "Stop, let Car A pass", "D": "Turn without stopping"}$q$::jsonb, $q$C$q$, $q$Unless a sign prohibits it, you may turn right on red only after a complete stop and after yielding to cross traffic and pedestrians. Car A has the green light, so Car B waits.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-right-on-red-0.png$q$, $q$El auto B tiene luz roja y quiere girar a la derecha. El auto A tiene luz verde. ¿Qué debe hacer el auto B?$q$, $q${"A": "Girar primero", "B": "Hacer luces y avanzar", "C": "Parar y ceder al auto A", "D": "Girar sin parar"}$q$::jsonb, $q$Salvo que una señal lo prohíba, puedes girar a la derecha con luz roja solo después de detenerte por completo y ceder el paso al tráfico transversal y a los peatones. El auto A tiene luz verde, así que el auto B espera.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car A has a red light and wants to turn right. Car B has a green light. What must Car A do?$q$, $q${"A": "Flash lights and go", "B": "Turn without stopping", "C": "Turn first", "D": "Stop, let Car B pass"}$q$::jsonb, $q$D$q$, $q$Unless a sign prohibits it, you may turn right on red only after a complete stop and after yielding to cross traffic and pedestrians. Car B has the green light, so Car A waits.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-right-on-red-90s.png$q$, $q$El auto A tiene luz roja y quiere girar a la derecha. El auto B tiene luz verde. ¿Qué debe hacer el auto A?$q$, $q${"A": "Hacer luces y avanzar", "B": "Girar sin parar", "C": "Girar primero", "D": "Parar y ceder al auto B"}$q$::jsonb, $q$Salvo que una señal lo prohíba, puedes girar a la derecha con luz roja solo después de detenerte por completo y ceder el paso al tráfico transversal y a los peatones. El auto B tiene luz verde, así que el auto A espera.$q$);
