insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car A is pulling out of a driveway. Who must Car A yield to?$q$, $q${"A": "No one", "B": "Pedestrian and Car B", "C": "Only Car B", "D": "Only the pedestrian"}$q$::jsonb, $q$B$q$, $q$When entering a road from a driveway or alley, stop before the sidewalk and yield to pedestrians, then yield to all vehicles on the road.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-driveway-exit-0.png$q$, $q$El auto A está saliendo de una entrada de cochera. ¿A quién debe ceder el paso el auto A?$q$, $q${"A": "A nadie", "B": "Al peatón y al auto B", "C": "Solo al auto B", "D": "Solo al peatón"}$q$::jsonb, $q$Al entrar a una calle desde una cochera o un callejón, detente antes de la acera y cede el paso a los peatones, y luego a todos los vehículos de la calle.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car B is pulling out of a driveway. Who must Car B yield to?$q$, $q${"A": "No one", "B": "Only Car A", "C": "Pedestrian and Car A", "D": "Only the pedestrian"}$q$::jsonb, $q$C$q$, $q$When entering a road from a driveway or alley, stop before the sidewalk and yield to pedestrians, then yield to all vehicles on the road.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-driveway-exit-90s.png$q$, $q$El auto B está saliendo de una entrada de cochera. ¿A quién debe ceder el paso el auto B?$q$, $q${"A": "A nadie", "B": "Solo al auto A", "C": "Al peatón y al auto A", "D": "Solo al peatón"}$q$::jsonb, $q$Al entrar a una calle desde una cochera o un callejón, detente antes de la acera y cede el paso a los peatones, y luego a todos los vehículos de la calle.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Car A is pulling out of a driveway. Who must Car A yield to?$q$, $q${"A": "No one", "B": "Only Car B", "C": "Only the pedestrian", "D": "Pedestrian and Car B"}$q$::jsonb, $q$D$q$, $q$When entering a road from a driveway or alley, stop before the sidewalk and yield to pedestrians, then yield to all vehicles on the road.$q$, $q$Right-of-Way Rules$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/rw-driveway-exit-270.png$q$, $q$El auto A está saliendo de una entrada de cochera. ¿A quién debe ceder el paso el auto A?$q$, $q${"A": "A nadie", "B": "Solo al auto B", "C": "Solo al peatón", "D": "Al peatón y al auto B"}$q$::jsonb, $q$Al entrar a una calle desde una cochera o un callejón, detente antes de la acera y cede el paso a los peatones, y luego a todos los vehículos de la calle.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Do not enter", "B": "Come to a full stop", "C": "Slow for a curve", "D": "Yield to traffic"}$q$::jsonb, $q$B$q$, $q$You must stop completely at the stop line, crosswalk, or before entering the intersection. Proceed only when it is safe and you have the right-of-way.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r1-1.png$q$, $q$¿Qué debe hacer cuando vea esta señal?$q$, $q${"A": "No entrar", "B": "Parar por completo", "C": "Reducir por curva", "D": "Ceder el paso"}$q$::jsonb, $q$Debe detenerse por completo en la línea de alto, paso de peatones o antes de entrar a la intersección. Continúe solo cuando sea seguro y tenga el derecho de paso.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Come to a full stop", "B": "Slow and yield", "C": "Keep right", "D": "Do not enter"}$q$::jsonb, $q$B$q$, $q$You must slow down and give the right-of-way to other traffic or pedestrians if needed. Be prepared to stop if necessary.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r1-2.png$q$, $q$¿Qué debe hacer cuando vea esta señal?$q$, $q${"A": "Parar por completo", "B": "Reducir y ceder", "C": "Mantenerse derecha", "D": "No entrar"}$q$::jsonb, $q$Debe reducir la velocidad y ceder el paso a otros vehículos o peatones si es necesario. Prepárese para detenerse si hace falta.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Keep right", "B": "No right turn", "C": "One-way traffic", "D": "Turn right only"}$q$::jsonb, $q$C$q$, $q$This is a ONE WAY sign showing that traffic on this street moves only to the right. You may not travel left against that direction.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r6-1r.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Manténgase a la der.", "B": "No vuelta a la der.", "C": "Tránsito en un sentido", "D": "Solo vuelta a la der."}$q$::jsonb, $q$Esta es una señal de UNA VÍA que indica que el tráfico en esta calle va solo hacia la derecha. No puede avanzar hacia la izquierda contra esa dirección.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Wrong-way ahead", "B": "Do not enter here", "C": "Stop ahead", "D": "Yield to traffic"}$q$::jsonb, $q$B$q$, $q$This sign means you must not enter the roadway or ramp beyond it. It marks an entrance where traffic is not allowed from your direction.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r5-1.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Sentido contrario", "B": "No entre aquí", "C": "Pare más adelante", "D": "Ceda el paso"}$q$::jsonb, $q$Esta señal significa que no debe entrar a la carretera o rampa más allá de ella. Marca una entrada donde no se permite el tráfico desde su dirección.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Stop for cross traffic", "B": "Proceed with care", "C": "Keep right ahead", "D": "Turn around safely"}$q$::jsonb, $q$D$q$, $q$This sign means you are going the wrong way on a one-way road or ramp. Do not continue; turn around safely when you can do so.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r5-1a.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Pare por tráfico", "B": "Siga con cuidado", "C": "Manténgase derecha", "D": "Dé la vuelta seguro"}$q$::jsonb, $q$Esta señal indica que va en sentido contrario en una vía o rampa de un solo sentido. No continúe; dé la vuelta con seguridad cuando pueda hacerlo.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Turn right only", "B": "No U-turn", "C": "Right lane ends", "D": "No right turn"}$q$::jsonb, $q$D$q$, $q$This sign means right turns are prohibited at this location. You must continue straight or follow another permitted movement.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-1.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Solo vuelta der.", "B": "No vuelta en U", "C": "Termina carril der.", "D": "No dar vuelta der."}$q$::jsonb, $q$Esta señal significa que está prohibido dar vuelta a la derecha en este lugar. Debe seguir recto o hacer otro movimiento permitido.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Yield to the right", "B": "Turn right only", "C": "Merge right now", "D": "Do not turn right"}$q$::jsonb, $q$D$q$, $q$When you see this sign, you may not make a right turn there. Obey the restriction and use another allowed direction.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-1.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Ceda a la derecha", "B": "Solo gire a la der.", "C": "Métase a la der.", "D": "No gire a la der."}$q$::jsonb, $q$Al ver esta señal, no puede dar vuelta a la derecha allí. Obedezca la restricción y use otra dirección permitida.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "No U-turn", "B": "No left turn", "C": "Keep left", "D": "Left lane ends"}$q$::jsonb, $q$B$q$, $q$This sign means left turns are prohibited at this location. You must continue straight or choose another permitted direction.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-2.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "No dar vuelta en U", "B": "No doblar a la izq.", "C": "Manténgase a izq.", "D": "Termina carril izq."}$q$::jsonb, $q$Esta señal significa que está prohibido doblar a la izquierda en este lugar. Debe seguir derecho o tomar otra dirección permitida.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Do not turn left", "B": "Turn left slowly", "C": "Yield to oncoming", "D": "Make a U-turn"}$q$::jsonb, $q$A$q$, $q$When you see this sign, you may not make a left turn there. Proceed straight or follow another allowed route.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-2.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "No doblar a la izq.", "B": "Doblar izq. despacio", "C": "Ceder al tráfico", "D": "Dar vuelta en U"}$q$::jsonb, $q$Al ver esta señal, no puede doblar a la izquierda allí. Siga derecho o tome otra ruta permitida.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Turn right ahead", "B": "Do not pass", "C": "Divided highway", "D": "Keep left"}$q$::jsonb, $q$D$q$, $q$This sign means you must pass to the left of an obstruction or divider. It directs traffic to keep left.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r4-8.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Gire a la derecha", "B": "No rebasar", "C": "Vía dividida", "D": "Manténgase a la izq."}$q$::jsonb, $q$Esta señal significa que debe pasar a la izquierda de una obstrucción o divisor. Indica al tráfico que se mantenga a la izquierda.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Stay in right lane", "B": "Merge from the left", "C": "Stop before island", "D": "Pass left of hazard"}$q$::jsonb, $q$D$q$, $q$When you see this sign, drive to the left of the obstruction or median. Do not pass on the right side of it.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r4-8.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Siga por derecha", "B": "Entren por izq.", "C": "Pare antes isla", "D": "Pase a la izq."}$q$::jsonb, $q$Al ver esta señal, conduzca a la izquierda de la obstrucción o mediana. No pase por el lado derecho de esta.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "No U-turn or left", "B": "Left lane ends", "C": "Turn left ahead", "D": "No right turn"}$q$::jsonb, $q$A$q$, $q$This sign means both U-turns and left turns are prohibited at this location.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-18.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "No vuelta en U ni izq", "B": "Termina carril izq", "C": "Gire a la izq adelante", "D": "No girar a la der"}$q$::jsonb, $q$Esta señal significa que están prohibidas tanto las vueltas en U como los giros a la izquierda en este lugar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "No U-turn", "B": "No turn on red", "C": "Yield to traffic", "D": "Stop here on red"}$q$::jsonb, $q$B$q$, $q$This sign means you may not make a turn while the traffic signal is red. Wait for a green signal before turning.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r10-11.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "No dar vuelta en U", "B": "No doblar en rojo", "C": "Ceda el paso", "D": "Pare aquí en rojo"}$q$::jsonb, $q$Esta señal significa que no puede doblar mientras la luz esté roja. Espere la luz verde antes de doblar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Turn after stopping", "B": "Wait for green", "C": "Yield, then turn", "D": "Make a U-turn"}$q$::jsonb, $q$B$q$, $q$With this sign, turning on a red light is prohibited. Remain stopped and do not turn until the signal turns green.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r10-11.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Girar tras detenerse", "B": "Esperar la luz verde", "C": "Ceder y luego girar", "D": "Hacer vuelta en U"}$q$::jsonb, $q$Con esta señal, está prohibido doblar con la luz roja. Permanezca detenido y no doble hasta que la señal cambie a verde.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Yield ahead", "B": "Keep intersection open", "C": "No U-turn", "D": "Stop here on red"}$q$::jsonb, $q$B$q$, $q$This sign means do not enter an intersection unless you can clear it completely. Blocking the intersection is prohibited.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r10-7.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Ceda el paso adelante", "B": "No bloquear el cruce", "C": "No vuelta en U", "D": "Pare aquí en rojo"}$q$::jsonb, $q$Esta señal significa que no debe entrar a una intersección a menos que pueda salir por completo. Está prohibido bloquear la intersección.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Yield here", "B": "Stop here on red", "C": "No turn on red", "D": "Stop ahead"}$q$::jsonb, $q$B$q$, $q$This sign tells drivers where to stop when the traffic signal is red. Stop at the marked line or location shown by the sign.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r10-6.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Ceda el paso aquí", "B": "Pare aquí en rojo", "C": "No girar en rojo", "D": "Pare más adelante"}$q$::jsonb, $q$Esta señal indica dónde debe detenerse cuando el semáforo está en rojo. Deténgase en la línea o lugar indicado por la señal.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Right lane: turn right", "B": "Keep right", "C": "Right shoulder ends", "D": "No right turn"}$q$::jsonb, $q$A$q$, $q$This sign means traffic in the right lane must turn right. You cannot continue straight from that lane.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-7r.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Carril der.: gire a la der.", "B": "Manténgase a la der.", "C": "Termina el acotamiento", "D": "No vuelta a la der."}$q$::jsonb, $q$Esta señal significa que el tráfico en el carril derecho debe girar a la derecha. No puede seguir recto desde ese carril.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Bike lane", "B": "Bike route", "C": "Share the road", "D": "No bicycles"}$q$::jsonb, $q$A$q$, $q$This sign marks a bicycle lane reserved for bicycles. Drivers should recognize that cyclists may be traveling there.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-17.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Carril para bicis", "B": "Ruta para bicis", "C": "Comparta la vía", "D": "No bicicletas"}$q$::jsonb, $q$Esta señal indica un carril para bicicletas reservado para bicicletas. Los conductores deben reconocer que los ciclistas pueden circular allí.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Road narrows", "B": "Do not pass", "C": "Keep right", "D": "Pass with care"}$q$::jsonb, $q$D$q$, $q$This sign means passing is allowed, but only when it can be done safely. Use extra caution and pass only if the way is clear.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r4-2.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Se estrecha la vía", "B": "No rebasar", "C": "Manténgase a la der.", "D": "Rebase con cuidado"}$q$::jsonb, $q$Esta señal significa que se permite rebasar, pero solo cuando se pueda hacer con seguridad. Tenga mucha precaución y rebase solo si el camino está despejado.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Stop before passing", "B": "Stay in right lane", "C": "Never pass here", "D": "Pass only if safe"}$q$::jsonb, $q$D$q$, $q$You may pass at this location, but only with care and when conditions make it safe. Make sure the opposing lane is clear before passing.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r4-2.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Pare antes rebasar", "B": "Siga en carril der.", "C": "Nunca rebase aquí", "D": "Rebase solo seguro"}$q$::jsonb, $q$Puede rebasar en este lugar, pero solo con cuidado y cuando las condiciones sean seguras. Asegúrese de que el carril contrario esté despejado antes de rebasar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Bus lane only", "B": "No passing zone", "C": "HOV lane only", "D": "Keep right"}$q$::jsonb, $q$C$q$, $q$This sign marks an HOV lane. Only vehicles with the posted minimum number of occupants may use it during the posted hours.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-11.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Solo carril bus", "B": "Prohibido rebasar", "C": "Solo carril HOV", "D": "Manténgase derecha"}$q$::jsonb, $q$Esta señal marca un carril HOV. Solo los vehículos con el número mínimo de ocupantes indicado pueden usarlo durante las horas indicadas.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do when you see this sign?$q$, $q${"A": "Use lane if qualified", "B": "Turn right only", "C": "Merge left now", "D": "Stop for all traffic"}$q$::jsonb, $q$A$q$, $q$You may enter or remain in the lane only if your vehicle has at least the posted number of occupants during the posted hours. Otherwise, use a different lane.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-11.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Úselo si califica", "B": "Solo vuelta derecha", "C": "Pásese a la izq.", "D": "Deténgase siempre"}$q$::jsonb, $q$Puede entrar o permanecer en el carril solo si su vehículo tiene al menos el número de ocupantes indicado durante las horas publicadas. De lo contrario, use otro carril.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Dead end ahead", "B": "Road narrows", "C": "Do not enter", "D": "Road work ahead"}$q$::jsonb, $q$A$q$, $q$This sign warns that the road ends ahead and does not continue through. Be prepared to turn around or choose another route.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w14-1.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Calle sin salida", "B": "Se estrecha la vía", "C": "No entre", "D": "Obras adelante"}$q$::jsonb, $q$Esta señal advierte que la vía termina más adelante y no continúa. Prepárese para dar la vuelta o elegir otra ruta.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you expect when you see this sign?$q$, $q${"A": "Keep right only", "B": "Road ends ahead", "C": "Merge to one lane", "D": "Cross traffic ahead"}$q$::jsonb, $q$B$q$, $q$A dead end sign means the road stops ahead with no through passage. Slow down as needed and plan another way out.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w14-1.png$q$, $q$¿Qué debe esperar al ver esta señal?$q$, $q${"A": "Manténgase der.", "B": "La vía termina", "C": "Un carril menos", "D": "Tráfico cruzado"}$q$::jsonb, $q$Una señal de calle sin salida significa que la vía termina más adelante y no sigue. Reduzca la velocidad si es necesario y planee otra salida.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Road work ahead", "B": "Narrow bridge", "C": "Do not enter", "D": "No outlet"}$q$::jsonb, $q$D$q$, $q$This warning sign means the road or street has no outlet to another roadway. It is not the same as a dead end sign, which indicates the road ends entirely.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w14-2.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Obras adelante", "B": "Puente angosto", "C": "No entre", "D": "Sin salida"}$q$::jsonb, $q$Esta señal de advertencia indica que la calle o carretera no tiene salida a otra vía. No es lo mismo que una señal de calle sin salida, que indica que la vía termina por completo.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Right lane ends", "B": "Road curves right", "C": "Keep right", "D": "No passing zone"}$q$::jsonb, $q$A$q$, $q$This warning sign means the right lane ends ahead. Drivers should prepare to merge left if they are in that lane.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w9-1.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Termina carril der.", "B": "Curva a la derecha", "C": "Manténgase derecha", "D": "Zona no rebasar"}$q$::jsonb, $q$Esta señal de advertencia significa que el carril derecho termina más adelante. Los conductores deben prepararse para incorporarse a la izquierda si van en ese carril.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Stop for a train", "B": "Merge left soon", "C": "Stay in right lane", "D": "Turn right ahead"}$q$::jsonb, $q$B$q$, $q$This sign warns that the right lane ends ahead. If you are in the right lane, merge left safely when possible.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w9-1.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Pare por un tren", "B": "Incorpórese a la izq.", "C": "Siga en carril der.", "D": "Gire a la der. adelante"}$q$::jsonb, $q$Esta señal advierte que el carril derecho termina más adelante. Si usted va en el carril derecho, incorpórese a la izquierda con seguridad cuando sea posible.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Loose gravel", "B": "Pavement ends", "C": "Soft shoulder", "D": "Road narrows"}$q$::jsonb, $q$B$q$, $q$This warning sign means the paved surface ends ahead. The road may continue as gravel or another unpaved surface.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w8-3.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Grava suelta", "B": "Termina el pavimento", "C": "Acotamiento blando", "D": "La vía se angosta"}$q$::jsonb, $q$Esta señal de advertencia significa que el pavimento termina más adelante. La carretera puede continuar con grava u otra superficie no pavimentada.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Stop before tracks", "B": "Slow for rough surface", "C": "Turn on headlights", "D": "Merge left now"}$q$::jsonb, $q$B$q$, $q$You should slow down and be ready for a change from pavement to an unpaved or rougher surface. Keep a firm grip on the wheel and avoid sudden moves.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w8-3.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Pare antes de rieles", "B": "Reduzca por superficie", "C": "Encienda las luces", "D": "Mézclese a la izq."}$q$::jsonb, $q$Debe reducir la velocidad y estar preparado para un cambio de pavimento a una superficie no pavimentada o más áspera. Mantenga firme el volante y evite movimientos bruscos.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Slippery when wet", "B": "Soft shoulder", "C": "Low shoulder", "D": "Shoulder drop-off"}$q$::jsonb, $q$B$q$, $q$This warning sign means the shoulder is soft and may not support your vehicle. Avoid driving onto the shoulder unless necessary.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w8-4.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Resbaloso si mojado", "B": "Acotamiento blando", "C": "Acotamiento bajo", "D": "Desnivel lateral"}$q$::jsonb, $q$Esta señal advierte que el hombro es blando y puede no sostener su vehículo. Evite conducir sobre el hombro salvo que sea necesario.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Stop ahead", "B": "Yield ahead", "C": "No passing zone", "D": "Merge ahead"}$q$::jsonb, $q$B$q$, $q$This warning sign tells you that a yield sign is ahead. Be prepared to slow down and give right-of-way if needed.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w3-2.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Pare más adelante", "B": "Ceda el paso adelante", "C": "Zona no rebasar", "D": "Incorporación adelante"}$q$::jsonb, $q$Esta señal de advertencia indica que hay una señal de ceda el paso más adelante. Prepárese para reducir la velocidad y ceder el paso si es necesario.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Prepare to yield", "B": "Come to a full stop", "C": "Do not pass", "D": "Speed up to merge"}$q$::jsonb, $q$A$q$, $q$This sign warns that a yield sign is ahead. Slow down and be ready to give right-of-way at the upcoming yield point.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w3-2.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Prepárese a ceder", "B": "Deténgase por completo", "C": "No rebase", "D": "Acelere para entrar"}$q$::jsonb, $q$Esta señal advierte que hay una señal de ceda el paso más adelante. Reduzca la velocidad y esté listo para ceder el paso en el próximo punto.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what must you do?$q$, $q${"A": "Keep right", "B": "Stop ahead", "C": "Do not pass", "D": "Yield ahead"}$q$::jsonb, $q$C$q$, $q$This sign tells drivers that passing is prohibited in this area. Stay in your lane and do not overtake other vehicles.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r4-1.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Manténgase der.", "B": "Pare más adelante", "C": "No rebasar", "D": "Ceda el paso"}$q$::jsonb, $q$Esta señal indica que está prohibido rebasar en esta zona. Permanezca en su carril y no adelante a otros vehículos.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what must you do from this lane?$q$, $q${"A": "Merge left", "B": "No left turn", "C": "Keep left", "D": "Turn left only"}$q$::jsonb, $q$D$q$, $q$This sign means the lane is reserved for left turns only. From this lane, you must make a left turn.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-5l.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer desde este carril?$q$, $q${"A": "Incorpórese izq.", "B": "No doblar izq.", "C": "Manténgase izq.", "D": "Doblar solo izq."}$q$::jsonb, $q$Esta señal indica que este carril es solo para dar vuelta a la izquierda. Desde este carril, debe doblar a la izquierda.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$This sign is posted ahead. What should you do?$q$, $q${"A": "Prepare for roundabout", "B": "Watch for bicycles", "C": "Stop at next sign", "D": "Merge into traffic"}$q$::jsonb, $q$A$q$, $q$This sign warns that a circular intersection (roundabout) is ahead. Slow down and be ready to yield to traffic already in the roundabout.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w2-6.png$q$, $q$Esta señal está más adelante. ¿Qué debe hacer?$q$, $q${"A": "Prepárese para rotonda", "B": "Cuidado con bicicletas", "C": "Pare en próxima señal", "D": "Incorpórese al tráfico"}$q$::jsonb, $q$Esta señal advierte que hay una intersección circular (rotonda) más adelante. Reduzca la velocidad y prepárese para ceder el paso al tráfico que ya está en la rotonda.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what must you do?$q$, $q${"A": "Yield to cross traffic", "B": "No passing ahead", "C": "Stay at or below limit", "D": "Stop if pedestrians"}$q$::jsonb, $q$C$q$, $q$This is a speed limit sign. You must not drive faster than the posted maximum speed shown on the sign.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r2-1.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Ceda al tráfico", "B": "No rebasar pronto", "C": "Ir al límite o menos", "D": "Pare por peatones"}$q$::jsonb, $q$Esta es una señal de límite de velocidad. No debe conducir más rápido que la velocidad máxima indicada en la señal.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what must you do?$q$, $q${"A": "Do not make a U-turn", "B": "No left turn", "C": "Yield to oncoming traffic", "D": "Turn left only"}$q$::jsonb, $q$A$q$, $q$This sign tells drivers that U-turns are prohibited at that location. Continue through or turn another permitted way instead.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r3-4.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "No haga vuelta en U", "B": "No gire a la izq.", "C": "Ceda al tráfico", "D": "Solo gire a izq."}$q$::jsonb, $q$Esta señal indica que las vueltas en U están prohibidas en ese lugar. Siga derecho o gire de otra manera permitida.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Merge left", "B": "No passing", "C": "Keep right", "D": "Stop ahead"}$q$::jsonb, $q$C$q$, $q$This sign tells drivers to pass to the right of an obstruction or divider. Stay to the right as you go by it.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-r4-7.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Únase a la izq.", "B": "No rebasar", "C": "Manténgase a la der.", "D": "Pare más adelante"}$q$::jsonb, $q$Esta señal le indica que pase a la derecha de una obstrucción o divisor. Manténgase a la derecha al pasarla.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Yield to oncoming", "B": "Keep right of median", "C": "Prepare for signal", "D": "Merge left now"}$q$::jsonb, $q$B$q$, $q$This sign warns that a divided highway begins ahead. Be prepared to stay to the right of the median or barrier.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w6-1.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Ceda al tráfico opuesto", "B": "Quédese a la derecha", "C": "Prepárese al semáforo", "D": "Incorpórese a la izq."}$q$::jsonb, $q$Esta señal advierte que comienza una carretera dividida más adelante. Prepárese para mantenerse a la derecha del separador o barrera.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you expect and do when you see this sign?$q$, $q${"A": "Merge right now", "B": "Watch for opposing cars", "C": "Keep left of island", "D": "Road ends ahead"}$q$::jsonb, $q$B$q$, $q$This sign warns that two-way traffic is ahead. Be ready for vehicles coming toward you and stay in your proper lane.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w6-3.png$q$, $q$¿Qué debe esperar y hacer al ver esta señal?$q$, $q${"A": "Mézclese a la der.", "B": "Ver tráfico opuesto", "C": "Manténgase izq.", "D": "La vía termina"}$q$::jsonb, $q$Esta señal advierte que más adelante hay tráfico en ambos sentidos. Esté atento a vehículos de frente y permanezca en su carril.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "No passing zone", "B": "Slow and be ready", "C": "Yield to cross traffic", "D": "Stop immediately"}$q$::jsonb, $q$B$q$, $q$This sign warns that a highway-rail grade crossing is ahead. Slow down, look and listen for trains, and be prepared to stop if needed.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w10-1.png$q$, $q$¿Qué debe hacer cuando vea esta señal?$q$, $q${"A": "No rebasar", "B": "Reduzca y prepárese", "C": "Ceda al tráfico", "D": "Pare de inmediato"}$q$::jsonb, $q$Esta señal advierte que hay un cruce de ferrocarril más adelante. Reduzca la velocidad, mire y escuche si vienen trenes, y esté listo para detenerse si es necesario.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "School zone ahead", "B": "Watch for people", "C": "Yield to merging", "D": "Road curves ahead"}$q$::jsonb, $q$B$q$, $q$This sign warns that pedestrians may be crossing ahead. Slow down and be ready to stop for people in or near the crosswalk.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w11-2.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Zona escolar adelante", "B": "Esté atento a peatones", "C": "Ceda al incorporarse", "D": "Curva adelante"}$q$::jsonb, $q$Esta señal advierte que puede haber peatones cruzando más adelante. Reduzca la velocidad y prepárese para detenerse por personas en o cerca del cruce peatonal.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Road curves right", "B": "Yield to oncoming", "C": "Watch for crossroad", "D": "Stop ahead"}$q$::jsonb, $q$C$q$, $q$This sign warns that a crossroad intersection is ahead. Slow down if needed and be ready for crossing traffic.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w2-1.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Curva a la derecha", "B": "Ceda al tráfico", "C": "Vigile cruce adelante", "D": "Pare adelante"}$q$::jsonb, $q$Esta señal advierte que hay una intersección con una vía transversal más adelante. Reduzca la velocidad si es necesario y esté atento al tráfico que cruza.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Stop at the bridge", "B": "Yield to oncoming", "C": "Slow for narrow span", "D": "Road ends ahead"}$q$::jsonb, $q$C$q$, $q$This sign warns that the bridge ahead is narrower than the roadway. Slow down and be prepared for reduced space as you cross.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w5-2.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Pare en el puente", "B": "Ceda al tráfico", "C": "Reduzca la velocidad", "D": "La vía termina"}$q$::jsonb, $q$Esta señal advierte que el puente adelante es más angosto que la carretera. Reduzca la velocidad y prepárese para menos espacio al cruzar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Yield to uphill cars", "B": "No passing ahead", "C": "Slow and use low gear", "D": "Stop at hill crest"}$q$::jsonb, $q$C$q$, $q$This sign warns of a steep downgrade ahead. Slow down and, if needed, shift to a lower gear to control your speed safely.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w7-1.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Ceda al subir", "B": "No rebase adelante", "C": "Reduzca y use baja", "D": "Pare en la cima"}$q$::jsonb, $q$Esta señal advierte una bajada empinada más adelante. Reduzca la velocidad y, si hace falta, use una marcha baja para controlar su velocidad.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Yield ahead", "B": "Watch for signal", "C": "Stop immediately", "D": "No passing zone"}$q$::jsonb, $q$B$q$, $q$This sign warns that a traffic signal is ahead. Slow down if needed and be prepared to stop or obey the upcoming signal.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w3-3.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Ceda el paso adelante", "B": "Esté atento al semáf.", "C": "Pare de inmediato", "D": "Zona no rebasar"}$q$::jsonb, $q$Esta señal advierte que hay un semáforo más adelante. Reduzca la velocidad si es necesario y prepárese para detenerse u obedecer la señal.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When you see this sign, what should you do?$q$, $q${"A": "Stop completely", "B": "No passing zone", "C": "Yield ahead", "D": "Watch for children"}$q$::jsonb, $q$D$q$, $q$This school advance warning sign tells you a school area is ahead. Slow down and watch carefully for children, crossings, and school-related traffic.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-s1-1.png$q$, $q$Cuando vea esta señal, ¿qué debe hacer?$q$, $q${"A": "Deténgase total", "B": "No rebasar", "C": "Ceda el paso", "D": "Cuidado con niños"}$q$::jsonb, $q$Esta señal de advertencia indica que hay una zona escolar más adelante. Reduzca la velocidad y esté atento a niños, cruces y tráfico escolar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Road work ahead", "B": "Steep hill ahead", "C": "Low clearance ahead", "D": "Narrow bridge ahead"}$q$::jsonb, $q$C$q$, $q$This sign warns that a low clearance is ahead. Drivers of tall vehicles should be prepared to avoid the route if needed.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w12-2.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Obras adelante", "B": "Pendiente fuerte", "C": "Poca altura adelante", "D": "Puente angosto"}$q$::jsonb, $q$Esta señal advierte que hay poca altura más adelante. Los conductores de vehículos altos deben estar preparados para evitar la ruta si es necesario.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when you see this sign?$q$, $q${"A": "Check vehicle height", "B": "Turn on high beams", "C": "Prepare to stop", "D": "Speed up to merge"}$q$::jsonb, $q$A$q$, $q$This sign warns of low clearance ahead. If your vehicle is tall, check its height and avoid proceeding if it may not fit safely.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w12-2.png$q$, $q$¿Qué debe hacer al ver esta señal?$q$, $q${"A": "Revise la altura", "B": "Encienda luces altas", "C": "Prepárese a parar", "D": "Acelere para entrar"}$q$::jsonb, $q$Esta señal advierte de poca altura más adelante. Si su vehículo es alto, revise su altura y no siga si no pasará con seguridad.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does this sign mean?$q$, $q${"A": "Two-way traffic", "B": "Pass either side", "C": "Keep right", "D": "Divided highway"}$q$::jsonb, $q$B$q$, $q$This double arrow sign means traffic may pass on either side of an obstruction or island. It does not mean two-way traffic or divided highway begins.$q$, $q$Signs, Signals & Markings$q$, null, $q$https://ksiqvvoqlzdihjubaxbm.supabase.co/storage/v1/object/public/images/Questions/Generated/mutcd-w12-1.png$q$, $q$¿Qué significa esta señal?$q$, $q${"A": "Tráfico en dos vías", "B": "Pase por ambos lados", "C": "Manténgase derecha", "D": "Autopista dividida"}$q$::jsonb, $q$Esta señal de doble flecha significa que el tráfico puede pasar por cualquiera de los dos lados de un obstáculo o isla. No significa tráfico en dos sentidos ni inicio de autopista dividida.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does a white diamond marking on a lane mean?$q$, $q${"A": "No trucks allowed", "B": "HOV lane", "C": "Exit-only lane", "D": "Passing lane only"}$q$::jsonb, $q$B$q$, $q$A white diamond marks a lane reserved for high-occupancy vehicles or other permitted users. It tells drivers that special lane-use rules apply there.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$¿Qué significa un rombo blanco marcado en un carril?$q$, $q${"A": "No se permiten camiones", "B": "Carril HOV", "C": "Carril solo para salida", "D": "Solo carril para rebasar"}$q$::jsonb, $q$Un rombo blanco marca un carril reservado para vehículos de alta ocupación u otros usuarios permitidos. Indica que allí se aplican reglas especiales de uso del carril.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Who may use an HOV lane?$q$, $q${"A": "Only large trucks", "B": "Vehicles meeting posted requirements", "C": "Any vehicle at any time", "D": "Only motorcycles"}$q$::jsonb, $q$B$q$, $q$HOV lanes are reserved for vehicles that meet the posted occupancy or use requirements. Always follow the signs showing who may use the lane and when.$q$, $q$Road Rules & Right-of-Way$q$, null, null, $q$¿Quién puede usar un carril HOV?$q$, $q${"A": "Solo camiones grandes", "B": "Vehículos que cumplan los requisitos", "C": "Cualquier vehículo en cualquier momento", "D": "Solo motocicletas"}$q$::jsonb, $q$Los carriles HOV están reservados para vehículos que cumplen los requisitos publicados de ocupación o uso. Siempre siga las señales que indican quién puede usar el carril y cuándo.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$How should you enter or leave an HOV lane?$q$, $q${"A": "Stop before changing lanes", "B": "Drive on the shoulder", "C": "Cross whenever traffic is light", "D": "Use designated entry and exit points"}$q$::jsonb, $q$D$q$, $q$Enter and leave an HOV lane only where signs and pavement markings allow it. Crossing restricted boundary lines is not permitted.$q$, $q$Turning & Lane Changes$q$, null, null, $q$¿Cómo debe entrar o salir de un carril HOV?$q$, $q${"A": "Deténgase antes de cambiar de carril", "B": "Conduzca por el acotamiento", "C": "Cruce cuando haya poco tráfico", "D": "Use puntos designados de entrada y salida"}$q$::jsonb, $q$Entre y salga de un carril HOV solo donde lo permitan las señales y las marcas del pavimento. No está permitido cruzar líneas de separación restringidas.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What is the main purpose of HOV or carpool lanes?$q$, $q${"A": "Provide scenic routes", "B": "Reduce congestion", "C": "Create truck shortcuts", "D": "Increase parking space"}$q$::jsonb, $q$B$q$, $q$HOV or carpool lanes move more people in fewer vehicles, which helps reduce traffic congestion. They encourage ridesharing and more efficient road use.$q$, $q$Lane Usage & Highway Driving$q$, null, null, $q$¿Cuál es el propósito principal de los carriles HOV o compartidos?$q$, $q${"A": "Ofrecer rutas escénicas", "B": "Reducir la congestión", "C": "Crear atajos para camiones", "D": "Aumentar el espacio para estacionar"}$q$::jsonb, $q$Los carriles HOV o compartidos mueven a más personas en menos vehículos, lo que ayuda a reducir la congestión. Fomentan compartir el viaje y un uso más eficiente de la vía.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What do broken lines next to an HOV lane indicate?$q$, $q${"A": "Parking is allowed there", "B": "Only trucks may cross", "C": "You may enter or exit there", "D": "Passing is required there"}$q$::jsonb, $q$C$q$, $q$You should enter or leave an HOV lane only where the lane boundary is broken. Solid lines mean you should not cross into or out of the lane.$q$, $q$Lane Usage & Highway Driving$q$, null, null, $q$¿Qué indican las líneas discontinuas junto a un carril HOV?$q$, $q${"A": "Se permite estacionar allí", "B": "Solo camiones pueden cruzar", "C": "Puede entrar o salir allí", "D": "Es obligatorio rebasar allí"}$q$::jsonb, $q$Debe entrar o salir de un carril HOV solo donde la línea divisoria es discontinua. Las líneas continuas significan que no debe cruzar para entrar ni salir.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$If you are driving alone, when may you use an HOV lane?$q$, $q${"A": "When signs allow your vehicle", "B": "Any time traffic is heavy", "C": "Whenever the lane is open", "D": "Only while passing slower cars"}$q$::jsonb, $q$A$q$, $q$HOV lanes are reserved for vehicles meeting posted requirements. A driver alone may use the lane only if signs specifically allow that vehicle type.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$Si maneja solo, ¿cuándo puede usar un carril HOV?$q$, $q${"A": "Cuando las señales lo permitan", "B": "Cada vez que haya mucho tráfico", "C": "Siempre que el carril esté abierto", "D": "Solo al rebasar autos lentos"}$q$::jsonb, $q$Los carriles HOV están reservados para vehículos que cumplen los requisitos indicados. Un conductor solo puede usar el carril únicamente si las señales permiten específicamente ese tipo de vehículo.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Where is a U-turn not allowed because drivers cannot see you well?$q$, $q${"A": "On a hill or curve", "B": "On a straight road", "C": "In a wide driveway", "D": "At a green light"}$q$::jsonb, $q$A$q$, $q$Do not make a U-turn on a hill or curve where other drivers cannot see you clearly. Limited visibility makes the turn unsafe.$q$, $q$Turning & Lane Changes$q$, null, null, $q$¿Dónde no se permite dar una vuelta en U porque otros conductores no pueden verlo bien?$q$, $q${"A": "En una colina o curva", "B": "En una vía recta", "C": "En una entrada amplia", "D": "Con luz verde"}$q$::jsonb, $q$No haga una vuelta en U en una colina o curva donde otros conductores no puedan verlo claramente. La visibilidad limitada hace que la maniobra sea peligrosa.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do if a sign says No U-Turn?$q$, $q${"A": "Honk before turning", "B": "Do not make the U-turn", "C": "Wait for a green light", "D": "Turn only if traffic is light"}$q$::jsonb, $q$B$q$, $q$A posted No U-Turn sign means U-turns are prohibited at that location. You must follow the sign and continue to a place where the turn is allowed.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$¿Qué debe hacer si una señal dice No U-Turn?$q$, $q${"A": "Toque la bocina antes de girar", "B": "No haga la vuelta en U", "C": "Espere la luz verde", "D": "Gire solo si hay poco tráfico"}$q$::jsonb, $q$Una señal de No U-Turn significa que las vueltas en U están prohibidas en ese lugar. Debe obedecer la señal y seguir hasta un lugar donde sí se permita girar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$How do you make a U-turn safely when it is allowed?$q$, $q${"A": "Stop in the middle first", "B": "Turn without checking mirrors", "C": "Signal, check traffic, turn carefully", "D": "Accelerate quickly through the turn"}$q$::jsonb, $q$C$q$, $q$When a U-turn is allowed, signal first, check for approaching traffic, and complete the turn only when it is safe. This helps avoid conflicts with other road users.$q$, $q$Turning & Lane Changes$q$, null, null, $q$¿Cómo hace una vuelta en U de manera segura cuando está permitida?$q$, $q${"A": "Deténgase primero en medio", "B": "Gire sin revisar los espejos", "C": "Señalice, revise tráfico, gire con cuidado", "D": "Acelere rápido durante el giro"}$q$::jsonb, $q$Cuando una vuelta en U está permitida, señalice primero, revise si viene tráfico y complete el giro solo cuando sea seguro. Esto ayuda a evitar conflictos con otros usuarios de la vía.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When should you slow down for a curve?$q$, $q${"A": "Only if tires skid", "B": "While steering harder", "C": "Before entering it", "D": "After the midpoint"}$q$::jsonb, $q$C$q$, $q$Slow down before you enter a curve so your tires keep better traction for steering. Braking hard in the curve can reduce control.$q$, $q$Driving Conditions & Hazards$q$, null, null, $q$¿Cuándo debe reducir la velocidad para una curva?$q$, $q${"A": "Solo si patinan llantas", "B": "Mientras gira más", "C": "Antes de entrar", "D": "Después del punto medio"}$q$::jsonb, $q$Reduzca la velocidad antes de entrar en una curva para que las llantas mantengan mejor tracción al dirigir. Frenar fuerte dentro de la curva puede reducir el control.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does a speed plaque below a curve sign mean?$q$, $q${"A": "Minimum legal speed", "B": "Truck speed only", "C": "Nighttime speed only", "D": "Safe advised curve speed"}$q$::jsonb, $q$D$q$, $q$A speed plaque under a curve warning sign shows an advisory speed for the curve. It warns that the curve should be taken at a safe, slower speed.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$¿Qué significa una placa de velocidad debajo de una señal de curva?$q$, $q${"A": "Velocidad mínima legal", "B": "Solo para camiones", "C": "Solo velocidad nocturna", "D": "Velocidad aconsejada segura"}$q$::jsonb, $q$Una placa de velocidad debajo de una señal de curva muestra una velocidad recomendada para la curva. Advierte que la curva debe tomarse a una velocidad segura y más baja.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$In a curve, where should your vehicle stay?$q$, $q${"A": "On the center line", "B": "Across both lanes", "C": "Centered in your lane", "D": "Near the shoulder"}$q$::jsonb, $q$C$q$, $q$Stay centered in your lane when driving through a curve. This gives you space from oncoming traffic and the road edge.$q$, $q$Vehicle Control & Maneuvers$q$, null, null, $q$En una curva, ¿dónde debe mantenerse su vehículo?$q$, $q${"A": "Sobre la línea central", "B": "En ambos carriles", "C": "Centrado en su carril", "D": "Cerca del hombro"}$q$::jsonb, $q$Manténgase centrado en su carril al conducir por una curva. Esto le da espacio del tráfico que viene de frente y del borde de la carretera.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$If you must brake in a curve, how should you do it?$q$, $q${"A": "Pump the brakes fast", "B": "Brake hard suddenly", "C": "Brake gently", "D": "Brake with one wheel off-road"}$q$::jsonb, $q$C$q$, $q$If braking is necessary in a curve, use gentle, smooth braking. Sudden hard braking can cause a skid and loss of control.$q$, $q$Driving Conditions & Hazards$q$, null, null, $q$Si debe frenar en una curva, ¿cómo debe hacerlo?$q$, $q${"A": "Bombee los frenos rápido", "B": "Frene fuerte de repente", "C": "Frene suavemente", "D": "Frene con una rueda fuera"}$q$::jsonb, $q$Si es necesario frenar en una curva, use un frenado suave y uniforme. Frenar fuerte de repente puede causar un derrape y pérdida de control.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Which is a warning sign of drowsy driving?$q$, $q${"A": "Stronger steering feel", "B": "Cooler air from vents", "C": "Brighter headlights", "D": "Missing traffic signs"}$q$::jsonb, $q$D$q$, $q$Missing traffic signs is a common warning sign of drowsy driving. It shows your attention is fading, so you may not notice important information ahead.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Cuál es una señal de advertencia de conducir con sueño?$q$, $q${"A": "Dirección más firme", "B": "Aire más frío de las rejillas", "C": "Faros más brillantes", "D": "No ver las señales de tránsito"}$q$::jsonb, $q$No ver las señales de tránsito es una señal común de advertencia de conducir con sueño. Indica que su atención está disminuyendo y puede no notar información importante adelante.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$If you feel sleepy while driving, what should you do?$q$, $q${"A": "Drive faster", "B": "Open windows only", "C": "Stop and rest", "D": "Turn up the radio"}$q$::jsonb, $q$C$q$, $q$If you feel sleepy, the safe action is to get off the road and rest. Opening windows or turning up the radio does not fix drowsiness.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$Si siente sueño mientras conduce, ¿qué debe hacer?$q$, $q${"A": "Conducir más rápido", "B": "Solo abrir las ventanas", "C": "Detenerse y descansar", "D": "Subir el volumen de la radio"}$q$::jsonb, $q$Si siente sueño, la acción segura es salir del camino y descansar. Abrir las ventanas o subir la radio no corrige la somnolencia.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What may happen when a driver is very drowsy?$q$, $q${"A": "They see farther ahead", "B": "They judge distance better", "C": "They react more quickly", "D": "They drift from their lane"}$q$::jsonb, $q$D$q$, $q$A very drowsy driver may drift from their lane because alertness and control are reduced. Drowsiness slows reactions and makes steering mistakes more likely.$q$, $q$Vehicle Control & Maneuvers$q$, null, null, $q$¿Qué puede pasar cuando un conductor tiene mucho sueño?$q$, $q${"A": "Ve más lejos hacia adelante", "B": "Calcula mejor la distancia", "C": "Reacciona más rápido", "D": "Se desvía de su carril"}$q$::jsonb, $q$Un conductor con mucho sueño puede desviarse de su carril porque disminuyen la atención y el control. La somnolencia retrasa las reacciones y hace más probables los errores al volante.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Repeated yawning while driving usually means you should:$q$, $q${"A": "Follow another car closely", "B": "Switch on high beams", "C": "Keep driving carefully", "D": "Find a safe place to stop"}$q$::jsonb, $q$D$q$, $q$Repeated yawning is a warning sign of drowsiness. When you notice it, you should stop driving and rest in a safe place.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$Bostezar repetidamente mientras conduce por lo general significa que debe:$q$, $q${"A": "Seguir muy de cerca a otro vehículo", "B": "Encender las luces altas", "C": "Seguir conduciendo con cuidado", "D": "Buscar un lugar seguro para detenerse"}$q$::jsonb, $q$Bostezar repetidamente es una señal de advertencia de somnolencia. Cuando lo note, debe dejar de conducir y descansar en un lugar seguro.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Your eyes keep closing briefly while driving. What does this mean?$q$, $q${"A": "Your speed is steady", "B": "Your headlights are dim", "C": "You are too drowsy", "D": "You need more air"}$q$::jsonb, $q$C$q$, $q$Brief eye closures while driving are a warning sign of dangerous drowsiness. It means you are not alert enough to drive safely.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$Tus ojos se cierran por momentos mientras conduces. ¿Qué significa?$q$, $q${"A": "Tu velocidad es constante", "B": "Tus faros están tenues", "C": "Estás demasiado somnoliento", "D": "Necesitas más aire"}$q$::jsonb, $q$Que los ojos se te cierren brevemente al conducir es una señal de advertencia de somnolencia peligrosa. Significa que no estás lo bastante alerta para conducir con seguridad.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What is the safest way to use a phone while driving?$q$, $q${"A": "Use speaker in traffic", "B": "Hold it briefly", "C": "Pull over safely first", "D": "Text at stoplights"}$q$::jsonb, $q$C$q$, $q$If you must use a phone, the safest choice is to pull over to a safe location first. Using a phone while the vehicle is moving takes your eyes and attention off driving.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Cuál es la manera más segura de usar un teléfono mientras conduce?$q$, $q${"A": "Usar altavoz en tráfico", "B": "Sostenerlo un momento", "C": "Orillarse con seguridad primero", "D": "Textear en semáforos"}$q$::jsonb, $q$Si tiene que usar un teléfono, la opción más segura es orillarse primero en un lugar seguro. Usar un teléfono mientras el vehículo está en movimiento le quita la vista y la atención al manejo.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Why can passengers be a driving distraction?$q$, $q${"A": "They improve your reaction time", "B": "They divide your attention", "C": "They shorten stopping distance", "D": "They make signs easier to see"}$q$::jsonb, $q$B$q$, $q$Passengers can distract you by drawing your eyes, thoughts, or hands away from driving. Safe driving requires your full attention to the road.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Por qué los pasajeros pueden ser una distracción al conducir?$q$, $q${"A": "Mejoran su tiempo de reacción", "B": "Dividen su atención", "C": "Acortan la distancia de frenado", "D": "Hacen más fáciles las señales"}$q$::jsonb, $q$Los pasajeros pueden distraerlo al desviar sus ojos, pensamientos o manos de la conducción. Manejar con seguridad requiere toda su atención en el camino.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$How can eating while driving affect you?$q$, $q${"A": "It can take hands off the wheel", "B": "It helps you focus", "C": "It reduces distractions", "D": "It improves vehicle control"}$q$::jsonb, $q$A$q$, $q$Eating while driving is a distraction because it can take your hands off the wheel and your mind off the road. You should keep both attention and control on driving.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Cómo puede afectarle comer mientras conduce?$q$, $q${"A": "Puede quitar manos del volante", "B": "Le ayuda a concentrarse", "C": "Reduce las distracciones", "D": "Mejora el control del vehículo"}$q$::jsonb, $q$Comer mientras conduce es una distracción porque puede quitar sus manos del volante y su mente del camino. Debe mantener la atención y el control en la conducción.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$While driving, what should you do with your phone?$q$, $q${"A": "Keep it out of reach", "B": "Hold it at stoplights", "C": "Use it in light traffic", "D": "Check it on straight roads"}$q$::jsonb, $q$A$q$, $q$Drivers should avoid using a phone while driving because it takes attention from the road. Keeping it out of reach helps reduce temptation and distraction.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$Mientras conduce, ¿qué debe hacer con su teléfono?$q$, $q${"A": "Mantenerlo fuera de alcance", "B": "Sostenerlo en semáforos", "C": "Usarlo con poco tráfico", "D": "Revisarlo en caminos rectos"}$q$::jsonb, $q$Los conductores deben evitar usar el teléfono mientras conducen porque les quita atención del camino. Mantenerlo fuera de alcance ayuda a reducir la tentación y la distracción.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$If passengers are distracting you, what is safest?$q$, $q${"A": "Drive faster to focus", "B": "Ask them to quiet down", "C": "Ignore the road briefly", "D": "Turn up the radio"}$q$::jsonb, $q$B$q$, $q$Passenger distractions can take your mind off driving. Asking passengers to lower the noise or stop distracting behavior helps you stay focused.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$Si los pasajeros lo distraen, ¿qué es lo más seguro?$q$, $q${"A": "Conducir más rápido para enfocarse", "B": "Pedirles que se tranquilicen", "C": "Ignorar el camino un momento", "D": "Subir el volumen de la radio"}$q$::jsonb, $q$Las distracciones de los pasajeros pueden apartar su mente de la conducción. Pedirles que bajen el ruido o dejen de distraerle ayuda a mantenerse enfocado.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What is the safest choice before eating while driving?$q$, $q${"A": "Eat only at red lights", "B": "Eat with one hand", "C": "Wait until you stop", "D": "Take small bites"}$q$::jsonb, $q$C$q$, $q$Eating while driving can take your hands, eyes, and attention away from driving. Waiting until you stop is the safest choice.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Cuál es la opción más segura antes de comer mientras conduce?$q$, $q${"A": "Comer solo en semáforos", "B": "Comer con una mano", "C": "Esperar hasta detenerse", "D": "Dar bocados pequeños"}$q$::jsonb, $q$Comer mientras conduce puede quitarle las manos, los ojos y la atención de la conducción. Esperar hasta detenerse es la opción más segura.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Before changing lanes, what should you do last?$q$, $q${"A": "Check your blind spot", "B": "Check mirrors", "C": "Signal your move", "D": "Brake hard"}$q$::jsonb, $q$A$q$, $q$Before changing lanes, check mirrors, signal, and then look over your shoulder for the blind spot. The blind spot check is the final step before moving.$q$, $q$Turning & Lane Changes$q$, null, null, $q$Antes de cambiar de carril, ¿qué debe hacer al final?$q$, $q${"A": "Revisar el punto ciego", "B": "Revisar los espejos", "C": "Señalar su movimiento", "D": "Frenar bruscamente"}$q$::jsonb, $q$Antes de cambiar de carril, revise los espejos, use la señal y luego mire sobre el hombro para revisar el punto ciego. La revisión del punto ciego es el paso final antes de moverse.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Why should you look over your shoulder before changing lanes?$q$, $q${"A": "To check the blind spot", "B": "To see behind both lanes", "C": "To judge tire pressure", "D": "To read road signs"}$q$::jsonb, $q$A$q$, $q$Mirrors do not show every area beside your vehicle. Looking over your shoulder helps you see a vehicle in your blind spot before changing lanes.$q$, $q$Turning & Lane Changes$q$, null, null, $q$¿Por qué debe mirar sobre el hombro antes de cambiar de carril?$q$, $q${"A": "Para revisar el punto ciego", "B": "Para ver detrás de ambos carriles", "C": "Para medir la presión de llantas", "D": "Para leer las señales"}$q$::jsonb, $q$Los espejos no muestran todas las áreas al lado de su vehículo. Mirar sobre el hombro le ayuda a ver un vehículo en su punto ciego antes de cambiar de carril.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What is the purpose of signaling before a lane change?$q$, $q${"A": "Claim the lane immediately", "B": "Increase your speed", "C": "Check your blind spot", "D": "Warn other road users"}$q$::jsonb, $q$D$q$, $q$Signal before changing lanes to let other road users know what you plan to do. A signal communicates your intention, but you must still make sure the lane is clear.$q$, $q$Turning & Lane Changes$q$, null, null, $q$¿Cuál es el propósito de señalar antes de cambiar de carril?$q$, $q${"A": "Tomar el carril de inmediato", "B": "Aumentar la velocidad", "C": "Revisar el punto ciego", "D": "Avisar a otros usuarios"}$q$::jsonb, $q$Señale antes de cambiar de carril para informar a otros usuarios de la vía lo que piensa hacer. La señal comunica su intención, pero aún debe asegurarse de que el carril esté libre.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$A broken white lane line means you may change lanes when$q$, $q${"A": "You are turning left", "B": "Traffic is stopped", "C": "The way is clear", "D": "Another driver waves"}$q$::jsonb, $q$C$q$, $q$A broken white lane line means lane changes are permitted when it is safe. You should change lanes only after checking traffic and making sure the way is clear.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$Una línea blanca discontinua significa que puede cambiar de carril cuando$q$, $q${"A": "Vaya a doblar a la izquierda", "B": "El tráfico esté detenido", "C": "El camino esté libre", "D": "Otro conductor le haga señas"}$q$::jsonb, $q$Una línea blanca discontinua significa que se permite cambiar de carril cuando sea seguro. Debe cambiar de carril solo después de revisar el tráfico y asegurarse de que el camino esté libre.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does a solid white line usually mean for lane changes?$q$, $q${"A": "Only trucks may cross", "B": "Discouraged or not allowed", "C": "Allowed without checking", "D": "Required at all times"}$q$::jsonb, $q$B$q$, $q$A solid white line means lane changes are discouraged, and in some situations not allowed. You should stay in your lane unless a lane change is permitted and can be made safely.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$¿Qué suele significar una línea blanca continua para cambiar de carril?$q$, $q${"A": "Solo camiones pueden cruzar", "B": "Desaconsejado o no permitido", "C": "Permitido sin revisar", "D": "Obligatorio en todo momento"}$q$::jsonb, $q$Una línea blanca continua significa que cambiar de carril está desaconsejado y, en algunas situaciones, no permitido. Debe permanecer en su carril a menos que se permita el cambio y pueda hacerse con seguridad.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$At a four-way stop, who goes first?$q$, $q${"A": "The fastest vehicle", "B": "The vehicle on the left", "C": "The first vehicle to arrive", "D": "The largest vehicle"}$q$::jsonb, $q$C$q$, $q$At a four-way stop, the first vehicle to come to a complete stop goes first. If two vehicles arrive together, other right-of-way rules apply.$q$, $q$Right-of-Way Rules$q$, null, null, $q$En una parada de cuatro vías, ¿quién va primero?$q$, $q${"A": "El vehículo más rápido", "B": "El vehículo a la izquierda", "C": "El primer vehículo en llegar", "D": "El vehículo más grande"}$q$::jsonb, $q$En una parada de cuatro vías, el primer vehículo que se detiene por completo va primero. Si dos vehículos llegan al mismo tiempo, se aplican otras reglas de derecho de paso.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What must you do at a four-way stop sign?$q$, $q${"A": "Stop completely before proceeding", "B": "Honk before entering", "C": "Yield only to trucks", "D": "Slow down and roll through"}$q$::jsonb, $q$A$q$, $q$A stop sign requires a complete stop before you proceed. Rolling through is not a legal stop and can endanger others.$q$, $q$Road Rules & Right-of-Way$q$, null, null, $q$¿Qué debe hacer en una señal de alto de cuatro vías?$q$, $q${"A": "Detenerse completamente antes de seguir", "B": "Tocar la bocina antes de entrar", "C": "Ceder el paso solo a camiones", "D": "Reducir velocidad y seguir sin parar"}$q$::jsonb, $q$Una señal de alto exige una detención completa antes de seguir. Pasar sin detenerse legalmente pone en peligro a los demás.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$At a four-way stop, who must you yield to before entering?$q$, $q${"A": "Pedestrians in or entering your crosswalk", "B": "Only vehicles turning left", "C": "Parked cars near the corner", "D": "Only drivers behind you"}$q$::jsonb, $q$A$q$, $q$Drivers must yield to pedestrians crossing or about to cross in their crosswalk. This applies even at a four-way stop.$q$, $q$Sharing the Road$q$, null, null, $q$En una parada de cuatro vías, ¿a quién debe ceder el paso antes de entrar?$q$, $q${"A": "Peatones en su cruce o entrando a él", "B": "Solo vehículos que giran a la izquierda", "C": "Autos estacionados cerca de la esquina", "D": "Solo conductores detrás de usted"}$q$::jsonb, $q$Los conductores deben ceder el paso a los peatones que cruzan o están por cruzar en su cruce. Esto también aplica en una parada de cuatro vías.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$At a four-way stop, if two vehicles arrive together, who should go first?$q$, $q${"A": "The driver on the right", "B": "The faster vehicle", "C": "The driver on the left", "D": "The larger vehicle"}$q$::jsonb, $q$A$q$, $q$When two vehicles reach a four-way stop at the same time, the driver on the left must yield to the driver on the right. This helps keep traffic moving safely and predictably.$q$, $q$Right-of-Way Rules$q$, null, null, $q$En una parada de cuatro vías, si dos vehículos llegan al mismo tiempo, ¿quién debe pasar primero?$q$, $q${"A": "El conductor de la derecha", "B": "El vehículo más rápido", "C": "El conductor de la izquierda", "D": "El vehículo más grande"}$q$::jsonb, $q$Cuando dos vehículos llegan al mismo tiempo a una parada de cuatro vías, el conductor de la izquierda debe ceder el paso al conductor de la derecha. Esto ayuda a que el tránsito fluya de manera segura y predecible.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Which direction do vehicles travel in a roundabout?$q$, $q${"A": "Either direction", "B": "Counterclockwise", "C": "Straight through", "D": "Clockwise"}$q$::jsonb, $q$B$q$, $q$In the United States, vehicles in a roundabout travel counterclockwise around the center island. This keeps all traffic moving in the same direction.$q$, $q$Road Rules & Right-of-Way$q$, null, null, $q$¿En qué dirección viajan los vehículos en una glorieta?$q$, $q${"A": "En cualquier dirección", "B": "En sentido antihorario", "C": "Directo hacia adelante", "D": "En el sentido horario"}$q$::jsonb, $q$En Estados Unidos, los vehículos en una glorieta circulan en sentido antihorario alrededor de la isla central. Esto mantiene a todo el tráfico moviéndose en la misma dirección.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$At a roundabout entrance, who must you yield to?$q$, $q${"A": "Vehicles behind you", "B": "Drivers entering after you", "C": "Vehicles already in it", "D": "Parked vehicles nearby"}$q$::jsonb, $q$C$q$, $q$When entering a roundabout, yield to traffic already circulating inside it. Enter only when there is a safe gap.$q$, $q$Right-of-Way Rules$q$, null, null, $q$En la entrada de una glorieta, ¿a quién debe ceder el paso?$q$, $q${"A": "A los vehículos detrás de usted", "B": "A los conductores que entren después", "C": "A los vehículos ya dentro", "D": "A los vehículos estacionados cerca"}$q$::jsonb, $q$Al entrar a una glorieta, ceda el paso al tráfico que ya circula dentro de ella. Entre solo cuando haya un espacio seguro.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Before entering a multi-lane roundabout, what should you do?$q$, $q${"A": "Change lanes inside", "B": "Choose the correct lane", "C": "Drive over the center", "D": "Stop in the circle"}$q$::jsonb, $q$B$q$, $q$In a multi-lane roundabout, select the proper lane before you enter based on where you plan to exit. Avoid changing lanes inside the roundabout.$q$, $q$Turning & Lane Changes$q$, null, null, $q$Antes de entrar a una glorieta de varios carriles, ¿qué debe hacer?$q$, $q${"A": "Cambiar de carril adentro", "B": "Elegir el carril correcto", "C": "Pasar sobre el centro", "D": "Detenerse dentro de la glorieta"}$q$::jsonb, $q$En una glorieta de varios carriles, elija el carril adecuado antes de entrar según la salida que piensa tomar. Evite cambiar de carril dentro de la glorieta.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you watch for when exiting a roundabout?$q$, $q${"A": "Passing on the left", "B": "Pedestrians and large trucks", "C": "Parking spaces ahead", "D": "Oncoming traffic in your lane"}$q$::jsonb, $q$B$q$, $q$When exiting a roundabout, watch for pedestrians in crosswalks and give large trucks extra space. Trucks may need more room to complete their turn safely.$q$, $q$Sharing the Road$q$, null, null, $q$¿Qué debe observar al salir de una glorieta?$q$, $q${"A": "Rebasar por la izquierda", "B": "Peatones y camiones grandes", "C": "Espacios para estacionar adelante", "D": "Tráfico de frente en su carril"}$q$::jsonb, $q$Al salir de una glorieta, observe a los peatones en los cruces peatonales y dé más espacio a los camiones grandes. Los camiones pueden necesitar más espacio para completar su giro con seguridad.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Why should you give large trucks extra space in roundabouts?$q$, $q${"A": "They may need more than one lane", "B": "They always stop inside", "C": "They travel faster than cars", "D": "They must yield to everyone"}$q$::jsonb, $q$A$q$, $q$Large trucks may need extra room to turn in a roundabout and can use more than one lane. Giving them space helps prevent conflicts and crashes.$q$, $q$Sharing the Road$q$, null, null, $q$¿Por qué debe dar más espacio a los camiones grandes en las rotondas?$q$, $q${"A": "Pueden necesitar más de un carril", "B": "Siempre se detienen adentro", "C": "Viajan más rápido que los autos", "D": "Deben ceder el paso a todos"}$q$::jsonb, $q$Los camiones grandes pueden necesitar espacio adicional para girar en una rotonda y pueden usar más de un carril. Darles espacio ayuda a prevenir conflictos y choques.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What does the 3-second following rule help you do?$q$, $q${"A": "Avoid using turn signals", "B": "Increase fuel economy", "C": "Drive closer at night", "D": "Keep a safe space cushion"}$q$::jsonb, $q$D$q$, $q$The 3-second rule helps you maintain enough space behind the vehicle ahead. This gives you more time to react and stop safely if traffic changes suddenly.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Para qué le ayuda la regla de los 3 segundos?$q$, $q${"A": "Evitar usar direccionales", "B": "Ahorrar más combustible", "C": "Manejar más cerca de noche", "D": "Mantener una distancia segura"}$q$::jsonb, $q$La regla de los 3 segundos le ayuda a mantener suficiente espacio detrás del vehículo de adelante. Esto le da más tiempo para reaccionar y detenerse con seguridad si el tráfico cambia de repente.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$When should you increase your following distance beyond 3 seconds?$q$, $q${"A": "On dry, clear roads", "B": "In rain or fog", "C": "When traffic is light", "D": "After passing an exit"}$q$::jsonb, $q$B$q$, $q$You should increase following distance in bad weather or other hazardous conditions. Reduced traction or visibility means you need more time and space to react.$q$, $q$Driving Conditions & Hazards$q$, null, null, $q$¿Cuándo debe aumentar su distancia de seguimiento a más de 3 segundos?$q$, $q${"A": "En caminos secos y despejados", "B": "Con lluvia o niebla", "C": "Cuando hay poco tráfico", "D": "Después de pasar una salida"}$q$::jsonb, $q$Debe aumentar la distancia de seguimiento con mal tiempo u otras condiciones peligrosas. La menor tracción o visibilidad significa que necesita más tiempo y espacio para reaccionar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Why should you follow motorcycles and large trucks at a greater distance?$q$, $q${"A": "They may stop or slow differently", "B": "They cannot brake on hills", "C": "They always drive under the speed limit", "D": "They must use the left lane"}$q$::jsonb, $q$A$q$, $q$Leave extra space behind motorcycles and large trucks because they can slow, stop, or block your view differently than cars. More distance gives you better visibility and more time to react.$q$, $q$Sharing the Road$q$, null, null, $q$¿Por qué debe seguir a las motocicletas y camiones grandes a mayor distancia?$q$, $q${"A": "Pueden frenar o reducir distinto", "B": "No pueden frenar en colinas", "C": "Siempre van bajo el límite", "D": "Deben usar el carril izquierdo"}$q$::jsonb, $q$Deje más espacio detrás de motocicletas y camiones grandes porque pueden reducir, detenerse o bloquear su vista de manera distinta a los autos. Más distancia le da mejor visibilidad y más tiempo para reaccionar.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$If a driver is tailgating you, what should you do?$q$, $q${"A": "Speed up well above traffic flow", "B": "Move closer to the car ahead", "C": "Brake suddenly to warn them", "D": "Increase space ahead of your vehicle"}$q$::jsonb, $q$D$q$, $q$If someone is following too closely, increase your following distance ahead when possible. This gives you more room to slow gradually and reduces the chance of a rear-end crash.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$Si un conductor le sigue muy de cerca, ¿qué debe hacer?$q$, $q${"A": "Acelerar mucho más que el tráfico", "B": "Acercarse más al auto adelante", "C": "Frenar de golpe para avisar", "D": "Aumentar el espacio delante"}$q$::jsonb, $q$Si alguien le sigue demasiado cerca, aumente su distancia de seguimiento adelante cuando sea posible. Esto le da más espacio para reducir la velocidad gradualmente y disminuye el riesgo de un choque por alcance.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What do orange signs usually warn drivers about?$q$, $q${"A": "School zones ahead", "B": "Road work ahead", "C": "Railroad crossing ahead", "D": "Hospital area ahead"}$q$::jsonb, $q$B$q$, $q$Orange signs warn of construction or maintenance areas ahead. They tell drivers to expect changing road conditions and slow down.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$¿Qué suelen advertir a los conductores las señales naranjas?$q$, $q${"A": "Zona escolar más adelante", "B": "Trabajos en la carretera", "C": "Cruce de ferrocarril adelante", "D": "Zona de hospital adelante"}$q$::jsonb, $q$Las señales naranjas advierten sobre zonas de construcción o mantenimiento más adelante. Le indican al conductor que espere cambios en la vía y reduzca la velocidad.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$In a work zone, who should you obey over regular signs?$q$, $q${"A": "Other drivers", "B": "Construction workers", "C": "Pedestrians nearby", "D": "A flagger"}$q$::jsonb, $q$D$q$, $q$In a work zone, follow the directions of a flagger. A flagger is controlling traffic safely through the area.$q$, $q$Road Rules & Right-of-Way$q$, null, null, $q$En una zona de trabajo, ¿a quién debe obedecer por encima de las señales normales?$q$, $q${"A": "A otros conductores", "B": "A trabajadores de construcción", "C": "A peatones cercanos", "D": "A un banderero"}$q$::jsonb, $q$En una zona de trabajo, debe seguir las instrucciones de un banderero. El banderero está controlando el tránsito de forma segura por el área.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$What should you do when lanes close in a work zone?$q$, $q${"A": "Merge carefully when directed", "B": "Drive on the shoulder", "C": "Speed up to pass everyone", "D": "Stop in your lane"}$q$::jsonb, $q$A$q$, $q$When a lane closes in a work zone, merge safely into the open lane as directed by signs or traffic control. Sudden stopping or using the shoulder is unsafe.$q$, $q$Turning & Lane Changes$q$, null, null, $q$¿Qué debe hacer cuando se cierran carriles en una zona de trabajo?$q$, $q${"A": "Incorporarse con cuidado cuando se indique", "B": "Conducir por el acotamiento", "C": "Acelerar para pasar a todos", "D": "Detenerse en su carril"}$q$::jsonb, $q$Cuando un carril se cierra en una zona de trabajo, incorpórese con seguridad al carril abierto según lo indiquen las señales o el control de tránsito. Detenerse de repente o usar el acotamiento es peligroso.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$How should you drive when entering a work zone?$q$, $q${"A": "Maintain normal highway speed", "B": "Change lanes often", "C": "Slow down and stay alert", "D": "Follow very closely"}$q$::jsonb, $q$C$q$, $q$Drivers should slow down and stay alert in work zones. Conditions can change quickly, and penalties for violations are often higher there.$q$, $q$Safe Driving & Defensive Driving$q$, null, null, $q$¿Cómo debe conducir al entrar en una zona de trabajo?$q$, $q${"A": "Mantener la velocidad normal de autopista", "B": "Cambiar de carril con frecuencia", "C": "Reducir la velocidad y mantenerse alerta", "D": "Seguir muy de cerca"}$q$::jsonb, $q$Los conductores deben reducir la velocidad y mantenerse alerta en las zonas de trabajo. Las condiciones pueden cambiar rápidamente, y las sanciones por infracciones suelen ser más altas allí.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$If a flagger signals you to stop in a work zone, what should you do?$q$, $q${"A": "Honk and continue slowly", "B": "Proceed if no workers show", "C": "Follow the car ahead", "D": "Stop and wait for directions"}$q$::jsonb, $q$D$q$, $q$In a work zone, you must obey a flagger's directions. If the flagger signals stop, remain stopped until told to proceed.$q$, $q$Signs, Signals & Markings$q$, null, null, $q$Si un banderillero le indica que se detenga en una zona de trabajo, ¿qué debe hacer?$q$, $q${"A": "Toque la bocina y siga despacio", "B": "Siga si no ve trabajadores", "C": "Siga al vehículo de adelante", "D": "Deténgase y espere instrucciones"}$q$::jsonb, $q$En una zona de trabajo, debe obedecer las instrucciones del banderillero. Si le indica que se detenga, permanezca detenido hasta que le digan que continúe.$q$);
insert into public.questions (question_text, answers, correct_answer, explanation, category, state, image_url, question_text_es, answers_es, explanation_es) values ($q$Why should you slow down in a work zone?$q$, $q${"A": "Workers may be close by", "B": "Speeding is allowed briefly", "C": "Orange signs cancel limits", "D": "Workers must move for you"}$q$::jsonb, $q$A$q$, $q$Workers, equipment and changing lanes can be very close to traffic in a work zone. Slowing down gives you time to react and protects everyone.$q$, $q$Driving Conditions & Hazards$q$, null, null, $q$¿Por qué debe reducir la velocidad en una zona de obras?$q$, $q${"A": "Puede haber trabajadores cerca", "B": "Se permite acelerar un rato", "C": "Las señales naranjas anulan límites", "D": "Los obreros deben apartarse"}$q$::jsonb, $q$En una zona de obras puede haber trabajadores, equipo y cambios de carril muy cerca del tráfico. Reducir la velocidad le da tiempo para reaccionar y protege a todos.$q$);
